import sys, json
data = json.load(sys.stdin)
with open('after-cpm-packages.json', 'w') as f:
    json.dump(data, f, indent=2)
print('Saved')
# Compare with baseline
with open('baseline-packages.json') as f:
    baseline = json.load(f)

# Build lookup: project_name -> framework -> package -> version
def build_index(d):
    idx = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        idx[name] = {}
        for fw in p['frameworks']:
            idx[name][fw['framework']] = {pkg['id']: pkg['resolvedVersion'] for pkg in fw['topLevelPackages']}
    return idx

b = build_index(baseline)
a = build_index(data)

print('\n=== CHANGES ===')
changes = False
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj, {}).keys()) + list(a.get(proj, {}).keys()))):
        bp = b.get(proj, {}).get(fw, {})
        ap = a.get(proj, {}).get(fw, {})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg)
            av = ap.get(pkg)
            if bv != av:
                changes = True
                print(f'{proj} ({fw}): {pkg} {bv} -> {av}')
if not changes:
    print('No changes detected')

print('\n=== UNCHANGED ===')
for proj in sorted(b.keys()):
    for fw in sorted(b.get(proj, {}).keys()):
        bp = b.get(proj, {}).get(fw, {})
        ap = a.get(proj, {}).get(fw, {})
        for pkg in sorted(bp.keys()):
            if bp.get(pkg) == ap.get(pkg):
                print(f'{proj} ({fw}): {pkg} {bp[pkg]}')
"

